func testNCMTributacaoToOneSetOpCsticmUsingCsticm(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a NCMTributacao
	var b, c Csticm

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, ncmTributacaoDBTypes, false, strmangle.SetComplement(ncmTributacaoPrimaryKeyColumns, ncmTributacaoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &b, csticmDBTypes, false, strmangle.SetComplement(csticmPrimaryKeyColumns, csticmColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &c, csticmDBTypes, false, strmangle.SetComplement(csticmPrimaryKeyColumns, csticmColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	for i, x := range []*Csticm{&b, &c} {
		err = a.SetCsticm(ctx, tx, i != 0, x)
		if err != nil {
			t.Fatal(err)
		}

		if a.R.Csticm != x {
			t.Error("relationship struct not set to correct value")
		}

		if x.R.NCMTributacaos[0] != &a {
			t.Error("failed to append to foreign relationship struct")
		}
		if a.CsticmsID != x.CsticmsID {
			t.Error("foreign key was wrong value", a.CsticmsID)
		}

		zero := reflect.Zero(reflect.TypeOf(a.CsticmsID))
		reflect.Indirect(reflect.ValueOf(&a.CsticmsID)).Set(zero)

		if err = a.Reload(ctx, tx); err != nil {
			t.Fatal("failed to reload", err)
		}

		if a.CsticmsID != x.CsticmsID {
			t.Error("foreign key was wrong value", a.CsticmsID, x.CsticmsID)
		}
	}
}
